CREATE DATABASE IF NOT EXISTS `supay` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `supay`;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS bitacora,cobro,venta,movimiento_inventario,repuesto_utilizado,reparacion,material,proveedor,instrumento,cliente,usuario;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE usuario (id_usuario INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,usuario VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,rol ENUM('administrador','luthier') NOT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,intentos_fallidos TINYINT UNSIGNED NOT NULL DEFAULT 0,bloqueado_hasta DATETIME NULL,creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_usuario_activo(usuario,activo)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE cliente (id_cliente INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,telefono VARCHAR(30),direccion VARCHAR(180)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE instrumento (id_instrumento INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,codigo_qr VARCHAR(80) NOT NULL UNIQUE,tipo VARCHAR(80) NOT NULL,descripcion TEXT,id_cliente INT UNSIGNED NOT NULL,CONSTRAINT fk_instrumento_cliente FOREIGN KEY(id_cliente) REFERENCES cliente(id_cliente),INDEX idx_instrumento_cliente(id_cliente)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE reparacion (id_reparacion INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_instrumento INT UNSIGNED NOT NULL,id_usuario INT UNSIGNED NOT NULL,diagnostico TEXT NOT NULL,estado ENUM('en_revision','en_reparacion','finalizado') NOT NULL DEFAULT 'en_revision',fecha_ingreso DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,costo DECIMAL(10,2) NOT NULL DEFAULT 0.00,CONSTRAINT fk_reparacion_instrumento FOREIGN KEY(id_instrumento) REFERENCES instrumento(id_instrumento),CONSTRAINT fk_reparacion_usuario FOREIGN KEY(id_usuario) REFERENCES usuario(id_usuario),CONSTRAINT chk_reparacion_costo CHECK(costo>=0),INDEX idx_reparacion_instrumento_fecha(id_instrumento,fecha_ingreso)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE proveedor (id_proveedor INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,contacto VARCHAR(120)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE material (id_material INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,categoria ENUM('maderas','cueros','pernos','herrajes') NOT NULL,stock DECIMAL(10,2) NOT NULL DEFAULT 0.00,stock_minimo DECIMAL(10,2) NOT NULL DEFAULT 0.00,id_proveedor INT UNSIGNED,CONSTRAINT fk_material_proveedor FOREIGN KEY(id_proveedor) REFERENCES proveedor(id_proveedor) ON DELETE SET NULL,CONSTRAINT chk_material_stock CHECK(stock>=0 AND stock_minimo>=0),INDEX idx_material_categoria_stock(categoria,stock)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE repuesto_utilizado (id_detalle INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_reparacion INT UNSIGNED NOT NULL,id_material INT UNSIGNED NOT NULL,cantidad DECIMAL(10,2) NOT NULL,CONSTRAINT fk_repuesto_reparacion FOREIGN KEY(id_reparacion) REFERENCES reparacion(id_reparacion),CONSTRAINT fk_repuesto_material FOREIGN KEY(id_material) REFERENCES material(id_material),CONSTRAINT chk_repuesto_cantidad CHECK(cantidad>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE movimiento_inventario (id_movimiento INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_material INT UNSIGNED NOT NULL,id_usuario INT UNSIGNED NOT NULL,tipo ENUM('entrada','salida') NOT NULL,cantidad DECIMAL(10,2) NOT NULL,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_movimiento_material FOREIGN KEY(id_material) REFERENCES material(id_material),CONSTRAINT fk_movimiento_usuario FOREIGN KEY(id_usuario) REFERENCES usuario(id_usuario),CONSTRAINT chk_movimiento_cantidad CHECK(cantidad>0),INDEX idx_movimiento_material_fecha(id_material,fecha)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE venta (id_venta INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_cliente INT UNSIGNED NOT NULL,id_instrumento INT UNSIGNED,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,total DECIMAL(10,2) NOT NULL,CONSTRAINT fk_venta_cliente FOREIGN KEY(id_cliente) REFERENCES cliente(id_cliente),CONSTRAINT fk_venta_instrumento FOREIGN KEY(id_instrumento) REFERENCES instrumento(id_instrumento),CONSTRAINT chk_venta_total CHECK(total>=0),INDEX idx_venta_fecha(fecha)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE cobro (id_cobro INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_reparacion INT UNSIGNED NOT NULL,monto DECIMAL(10,2) NOT NULL,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_cobro_reparacion FOREIGN KEY(id_reparacion) REFERENCES reparacion(id_reparacion),CONSTRAINT chk_cobro_monto CHECK(monto>0),INDEX idx_cobro_fecha(fecha)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE bitacora (id_log BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_usuario INT UNSIGNED,accion VARCHAR(80) NOT NULL,detalle VARCHAR(500),ip VARCHAR(45),fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_bitacora_usuario FOREIGN KEY(id_usuario) REFERENCES usuario(id_usuario) ON DELETE SET NULL,INDEX idx_bitacora_fecha(fecha),INDEX idx_bitacora_usuario(id_usuario)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
